/// <summary>
/// SalesInvoiceLineV3Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesInvoiceLineV3Entity))]
final class METSalesInvoiceLineV3Entity_Extension
{
    

}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();
        //MPJ_24809 Returns Claims
        InventItemBarcode   metInventItemBarcodeStd;
        select firstonly itemBarCode from metInventItemBarcodeStd
            where metInventItemBarcodeStd.itemId    == this.ProductNumber &&
                  metInventItemBarcodeStd.UnitID    == this.SalesUnitSymbol;

        this.METGTIN                = metInventItemBarcodeStd.itemBarCode;

        METSalesLine    metSalesLine;
        SalesLine       metSalesLineStd;
        select sum(SalesQty) from metSalesLineStd
            exists join metSalesLine
            where metSalesLine.InvoiceLineNumber == this.LineCreationSequenceNumber &&
                  metSalesLine.InvoiceNumber     == this.InvoiceNumber &&
                  metSalesLine.SalesLine         == metSalesLine.RecId &&
                  metSalesLineStd.SalesType      == SalesType::ReturnItem;
        
        this.METCurrentClaimedQty   = metSalesLineStd.SalesQty;

    }
